const STEP = 284;

/**
 * Initialise the chapter slider.
 */
export const init = () => {
    const container = document.getElementById('oc-chapters-navigation');
    const slider = document.getElementById('oc-chapters-slider');
    if (!container || !slider) {
        return;
    }

    const buttons = container.getElementsByClassName('chapters-nav-btn');
    const getItems = () => Array.from(slider.getElementsByClassName('oc-chapter-item'));
    const last = getItems().length - 1;
    let position = Math.max(0, getItems().findIndex((item) => item.classList.contains('active')));

    const isMobile = window.matchMedia('(max-width: 767.98px)').matches;
    // Desktop: the template already offsets the active chapter via transform.
    const origin = isMobile ? 0 : position;
    let margin = 0;

    const update = () => {
        slider.style.translate = margin + 'px 0';
        buttons[0].classList.toggle('inactive', position <= 0);
        buttons[1].classList.toggle('inactive', position >= last);
        getItems().forEach((item, i) => item.classList.toggle('center', i === position));
    };

    const goTo = (target) => {
        if (target < 0 || target > last) {
            return;
        }
        position = target;
        margin = -(target - origin) * STEP;
        update();
    };

    goTo(position);

    buttons[0].addEventListener('click', () => goTo(position - 1));
    buttons[1].addEventListener('click', () => goTo(position + 1));

    // Keep the slider in sync when a chapter gets keyboard focus.
    slider.addEventListener('focusin', (event) => {
        const index = getItems().indexOf(event.target.closest('.oc-chapter-item'));
        if (index >= 0) {
            goTo(index);
        }
    });
};